from typing import Protocol
class HasName(Protocol):
    name: str
class User:
    def __init__(self, name: str): self.name = name
def label(item: HasName) -> str:
    return item.name.upper()
print(label(User('Mina')))

from typing import Protocol
class Writer(Protocol):
    def write(self, text: str) -> int: ...
class ConsoleWriter:
    def write(self, text: str) -> int:
        print(text)
        return len(text)
print(ConsoleWriter().write('saved'))

from typing import Protocol
class Clock(Protocol):
    def now(self) -> str: ...
class FixedClock:
    def now(self) -> str: return '2026-11-20'
def stamp(clock: Clock) -> str: return clock.now()
print(stamp(FixedClock()))

from typing import Protocol
class Closeable(Protocol):
    def close(self) -> None: ...
class Resource:
    def close(self) -> None: print('closed')
resource: Closeable = Resource()
resource.close()
